package com.thurdass.system2a.dto.response;
import com.thurdass.system2a.entity.*; import java.time.*; import java.util.*;
public final class SchoolResponses { private SchoolResponses(){} public record SubjectView(Long id,String name,String shortName,Long classroomId){public static SubjectView of(Subject x){return new SubjectView(x.getId(),x.getName(),x.getShortName(),x.getClassroom().getId());}} public record TeacherView(Long id,String name,String email,boolean active){public static TeacherView of(Teacher x){return new TeacherView(x.getId(),x.getName(),x.getEmail(),x.isActive());}} public record ScheduleView(Long id,Long classroomId,Long subjectId,Long teacherId,DayOfWeek dayOfWeek,LocalTime startTime,LocalTime endTime){public static ScheduleView of(ClassSchedule x){return new ScheduleView(x.getId(),x.getClassroom().getId(),x.getSubject().getId(),x.getTeacher()==null?null:x.getTeacher().getId(),x.getDayOfWeek(),x.getStartTime(),x.getEndTime());}} }
